func (q *Queries) ListHosts(ctx context.Context, arg ListHostsParams) ([]ListHostsRow, error) {
	rows, err := q.db.Query(ctx, listHosts,
		arg.Scope,
		arg.WorkspaceID,
		arg.NamespaceID,
		arg.Origin,
		arg.AgentStatus,
		arg.Search,
		arg.SortField,
		arg.SortOrder,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListHostsRow{}
	for rows.Next() {
		var i ListHostsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.DisplayName,
			&i.Description,
			&i.Hostname,
			&i.Os,
			&i.Arch,
			&i.CpuCores,
			&i.MemoryMb,
			&i.DiskGb,
			&i.Scope,
			&i.WorkspaceID,
			&i.NamespaceID,
			&i.Status,
			&i.StatusMessage,
			&i.SshPort,
			&i.AgentPort,
			&i.MonitorStatus,
			&i.MonitorMessage,
			&i.LogAgentStatus,
			&i.LogAgentMessage,
			&i.Origin,
			&i.ConnectivityMode,
			&i.ReportedIps,
			&i.ReportedPrimaryIp,
			&i.PrimaryIpOverride,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Virtualization,
			&i.CpuModel,
			&i.CpuSockets,
			&i.CpuCoresPerSocket,
			&i.CpuThreadsPerCore,
			&i.KernelVersion,
			&i.SystemVendor,
			&i.ProductName,
			&i.BiosVersion,
			&i.SerialNumber,
			&i.Timezone,
			&i.OsID,
			&i.OsVersionID,
			&i.BiosDate,
			&i.BoardName,
			&i.BoardSerial,
			&i.ChassisType,
			&i.AssetTag,
			&i.DefaultGateway,
			&i.KernelCmdline,
			&i.ClockSync,
			&i.CreatorName,
			&i.WorkspaceName,
			&i.NamespaceName,
			&i.AgentID,
			&i.AgentStatus,
			&i.AgentVersion,
			&i.AgentConnectedAt,
			&i.AgentLastSeenAt,
			&i.AgentConflictAt,
			&i.AgentForeignMachineAt,
			&i.AgentForeignMachineUuid,
			&i.ImageGroupSize,
			&i.MetricsSampledAt,
			&i.MetricsCpuUsedPct,
			&i.MetricsMemUsedPct,
			&i.MetricsDiskUsedPct,
			&i.MetricsDiskUsedPath,
			&i.MetricsDiskUsedBytes,
			&i.MetricsDiskTotalBytes,
			&i.MetricsLoad1,
			&i.MetricsLoad5,
			&i.MetricsLoad15,
			&i.MetricsNetRxBps,
			&i.MetricsNetTxBps,
			&i.MetricsCpuTrend,
			&i.AlertsFiring,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateHost = `-- name: UpdateHost :execrows
UPDATE hosts
SET display_name = $1,
    description  = $2,
    updated_at   = now()
WHERE id = $3
  AND ($4::BIGINT IS NULL OR workspace_id IS NOT DISTINCT FROM $4::BIGINT)
  AND ($5::BIGINT IS NULL OR namespace_id IS NOT DISTINCT FROM $5::BIGINT)
`

type UpdateHostParams struct {
	DisplayName       string `json:"display_name"`
	Description       string `json:"description"`
	ID                int64  `json:"id"`
	WorkspaceIDFilter *int64 `json:"workspace_id_filter"`
	NamespaceIDFilter *int64 `json:"namespace_id_filter"`
}

// Only the two fields a human owns. Everything else on this row is
// either agent-reported (and would be overwritten on the next heartbeat)
// or structural (scope, origin), so there is nothing else to expose.
func (q *Queries) UpdateHost(ctx context.Context, arg UpdateHostParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateHost,
		arg.DisplayName,
		arg.Description,
		arg.ID,
		arg.WorkspaceIDFilter,
		arg.NamespaceIDFilter,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
